#!/usr/bin/env python3 -I
import json,re,collections as C,sys
R='/tank/cyrus-library-staging/_reference-mods/analysis/per_item.jsonl'
W='/tank/dev-worktrees/cyrus-distill/services/modbuilder/'
pl=[r for r in map(json.loads,open(R)) if 'api_classes' in r]
txt=''.join(open(W+'sheets/%s.md'%v).read() for v in ['1.21.1','1.21.4','1.21.8','1.21.11'])
txt+=open(W+'prompts.js').read()+open(W+'rules/failure-rules.json').read()
ev=C.Counter();me=C.Counter();cl=C.Counter()
for p in pl:
    for c in p['api_classes']:
        cl[c]+=1
        if c.endswith('Event') and ('/event/' in c or c.startswith('com/destroystokyo') or 'paper/event' in c): ev[c]+=1
    for m in p['api_methods']: me[m]+=1
def simple(c): return c.split('/')[-1].replace('$','.')
out={'events':[],'methods':[]}
for c,n in ev.most_common():
    if simple(c) not in txt and n>=3: out['events'].append((c.replace('/','.'),n))
skip=re.compile(r'^(java|kotlin|com/google|org/slf4j|org/yaml|org/apache|net/md_5)')
for m,n in me.most_common():
    cls,_,meth=m.rpartition('.')
    if n<8 or skip.match(cls) or meth=='<init>': continue
    if not (cls.startswith('org/bukkit') or cls.startswith('io/papermc') or cls.startswith('com/destroystokyo') or cls.startswith('net/kyori')): continue
    if meth not in txt: out['methods'].append((cls.replace('/','.')+'.'+meth,n))
json.dump(out,open('s1_gap.json','w'),indent=0)
print(len(out['events']),len(out['methods']))
print(out['events'][:70]); print(out['methods'][:120])
E
python3 -I s1_gap.py

