// Version cheat sheets (sheets/<ver>.md, every claim checked with javap against
// the Paper API jar of that version) and the reviewed failure rules. Only the
// sheet for the requested version is injected. MB_SHEETS=off / MB_RULES=off
// disable them (used by the eval to measure their effect).
const SHEETS_ON = process.env.MB_SHEETS !== "off";
const RULES_ON = process.env.MB_RULES !== "off";
const SHEETS = {};
function sheetFor(v) {
  if (!SHEETS_ON) return "";
  if (!(v in SHEETS)) {
    try { SHEETS[v] = fs.readFileSync(path.join(__dirname, "sheets", `${v}.md`), "utf8").trim(); } catch { SHEETS[v] = ""; }
  }
  return SHEETS[v];
}
function knowledgeVersion() {
  return `${SHEETS_ON ? "sheets" : "nosheets"}+${RULES_ON ? RULES.version : "norules"}${PERF.enabled() ? `+${PERF.PERF_VERSION}` : ""}`;
}

// Cyrus perf safety (2026-10-11, ChunkMirror incident): the PERFORMANCE section + the NxPerf API sheet. Appended to every
// generated build's system prompt while MB_PERF_SAFETY is on (default); fixed text, so it caches per version. The
// watchdog itself is injected by perf.js before javac, whatever the model writes.
const PERF_SECTION = `

PERFORMANCE (rule 10; the build service checks it and every build is load-tested on a real server. Limits are DEFAULTS the server owner can raise, never caps on what they choose):
10. Every piece of work must be BOUNDED. A Minecraft server has 50 ms per tick for everything; a plugin that loops over the whole world, copies changes into every chunk or spawns without a limit drops a real server to 1 TPS. So:
- Never iterate all loaded chunks, all entities or all blocks of a world (getLoadedChunks(), world.getEntities(), getLivingEntities()) in an event handler or a repeating task. Work near players instead: player.getNearbyEntities(r, r, r) / location.getNearbyEnt
- Per tick: at most perf.max-work-per-tick block changes / entity updates / chunk operations (default 64). Every setType / setBlockData / breakNaturally inside a loop (a vein, a fill, a regeneration) goes through the queue or a take: NxPerf.take("blocks") befo
- Spawning: before every spawn call if (!NxPerf.spawnAllowed("<feature>", location.getChunk())) skip it (5 per second and 20 living mobs per chunk by default; perf.max-entities-per-second / perf.max-entities-per-chunk raise them). Copies/clones of mobs never s
- Explosions: if (!NxPerf.rate("explosions", 5)) skip; power at most 4; no explosion that triggers another without a generation limit.
- Repeating work only through NxPerf.timer("<feature>", delayTicks, periodTicks, () -> { ... }) (not runTaskTimer or BukkitRunnable.runTaskTimer, also not for an autosave or a countdown; keep the returned NxPerf.Timer, it has cancel()); one-off delays (runTask
- Never react to a change your own code made (no feedback loops through your own events): wrap re-entrant work in if (!NxPerf.enter("<key>")) return; try { ... } finally { NxPerf.exit("<key>"); }. No recursion through events, no while(true).
- Remembered data is bounded: lists/maps that grow with play (logs, queues, remembered changes) have a configured maximum (drop the oldest), stored per chunk/player key so one lookup never scans everything.
- Every limit is a config.yml setting with a SAFE default (radius 4 chunks / 16 blocks, per-tick 64 or less, mob copying off). The owner may raise it: HONOUR the saved value (log one warning naming the likely cost when it is above the recommended maximum; neve
NxPerf API (already in the plugin as <your package>.nxperf.NxPerf: import dev.nxeon.plugins.<lowercase plugin name>.nxperf.NxPerf; never write or edit NxPerf files; the build service starts it in onEnable): boolean take(String budget) / take(String budget, int
const PERF_ON = () => PERF.enabled();

function knowledge(mcVersion) {
  const parts = [];
  const sheet = sheetFor(mcVersion);
  if (sheet) parts.push(`API REFERENCE for Paper ${mcVersion} (verified against the jar you compile with; when it disagrees with your memory, it is right):\n${sheet}`);
  const rules = RULES_ON ? rulesFor(mcVersion) : [];
  if (rules.length) parts.push(`LESSONS FROM EARLIER FAILED BUILDS (follow every one):\n${rules.map((r) => `- ${r.rule}`).join("\n")}`);
  return parts.length ? `\n\n${parts.join("\n\n")}` : "";
}

// Cyrus R1 asset slice: the TEXTURES section. Appended to the system prompt ONLY when the build request allows
// textures (the portal's plan-tier gate said yes AND the version has item model definitions). Without it the system
// prompt is byte-identical to before. The per-mod namespace is in the user turn (assetsBlock), so this text stays
// the same for every texture build of a version and is cached like the rest of the prompt.
let EXAMPLE = "";
try { EXAMPLE = JSON.stringify(JSON.parse(fs.readFileSync(path.join(__dirname, "texture-example.json"), "utf8"))); } catch { EXAMPLE = ""; }
const TEXTURE_SECTION = `

CUSTOM TEXTURES (allowed for this build). The server owner's plan includes custom item textures, so rule 2 is extended: you may also create and edit texture spec files at assets/textures/<name>.json (nowhere else under assets/). Nxeon draws every spec into a r
- One file per custom item look, at most ${MAX_TEXTURES}. The file name is the texture name: 2-32 chars, lowercase letters, digits and underscores, starting with a letter; "name" inside must be the same.
- Format (Nxeon texture DSL, JSON): {"name": "...", "size": 16, "palette": {"key": "#rrggbb", ...}, "mirror": false, "ops": [...]}. size is 16, 32 or 64 (use 16 like vanilla items; 32 only when the item truly needs the detail). palette has 1-24 colours, keys a
- Art direction (vanilla style, one Style DNA for the whole mod): transparent background with a clear silhouette filling roughly a third to two thirds of the canvas; per material a short ramp of 3-5 shades from dark to light, lit from the top-left; flat areas,
- Automatic checks (failures come back to you like compile errors): pixels fully clear or fully solid, not empty and not a solid square, at most 32 distinct colours at 16 px (48 at 32 px, 64 at 64 px; fail above 48 / 96 / 128), clear contrast between the darke
- Original art only: never copy or recreate Minecraft's own textures, another game's art, logos or real brands.
- The plugin must use each texture: every custom item gets its look with the 1.21.4+ item model API, using the reserved namespace from the request exactly:
    ItemMeta meta = stack.getItemMeta(); meta.setItemModel(new NamespacedKey("<namespace>", "<texture name>")); stack.setItemMeta(meta);
  Keep a fitting vanilla base Material (its behaviour stays). Do not use setCustomModelData, and never send resource packs from the plugin (no setResourcePack/addResourcePack): Nxeon sends the pack.
- In modbuilder.json "howToUse", say that players accept the server resource pack when they join to see the custom items.${EXAMPLE ? `
- Example spec (a 16 px ruby sword): ${EXAMPLE}` : ""}`;

// Cyrus r35 legacy (1.21.1): the same TEXTURE section with the plugin bullet for the pre-1.21.4 custom-model-data path
// (lib/cyrus/itemmodel/legacy.ts). Used only when the request says assets.legacy (MB_LEGACY_TEXTURES on the builder);
// the mod's number block goes in the user turn (assetsBlock). Fixed text, so it caches per version like the 1.21.4+ one.
const LEGACY_CARRIER_LIST = Object.keys(require("./itemmodel-spec.js").LEGACY_CARRIERS).join(", ");
const LEGACY_TEXTURE_SECTION = TEXTURE_SECTION.replace('- The plugin must use each texture: every custom item gets its look with the 1.21.4+ item model API, using the reserved namespace from the request exactly:\n    ItemMeta meta = stack.getItemMeta(); meta.s
    1. pick a vanilla CARRIER item for it from this list only: ${LEGACY_CARRIER_LIST}. Its behaviour stays (a sword carrier still hits like that sword).
    2. give it a number from this mod's custom model data block (in the request) and write the binding in assets/legacy-models.json: {"items": [{"texture": "<texture name>", "base": "<carrier>", "cmd": <number>}, ...]} (one entry per texture, every number diff
    3. in the plugin: ItemStack stack = new ItemStack(Material.<CARRIER>); ItemMeta meta = stack.getItemMeta(); meta.setCustomModelData(<number>); stack.setItemMeta(meta);
  Use exactly the numbers from assets/legacy-models.json. Never call setItemModel, and never send resource packs from the plugin (no setResourcePack/addResourcePack): Nxeon sends the pack. Item looks per state (pulling, aiming, modes) are not available on this
if (!LEGACY_TEXTURE_SECTION.includes("setCustomModelData")) throw new Error("LEGACY_TEXTURE_SECTION: the plugin bullet was not replaced");

// Cyrus R1 sound slice: the SOUNDS section, appended ONLY when the request allows sounds (plan gate said yes). Two
// fixed variants (with / without the Nxeon sound library) so each still caches per version; the namespace and the
// catalog path go in the user turn (assetsBlock).
let SOUND_EXAMPLE = "";
try { SOUND_EXAMPLE = JSON.stringify(JSON.parse(fs.readFileSync(path.join(__dirname, "sound-example.json"), "utf8"))); } catch { SOUND_EXAMPLE = ""; }
const roleLimits = SS.SOUND_ROLES.map((r) => `${r} (at most ${SS.ROLE_PROFILE[r].maxSeconds} s)`).join(", ");
const presetDocs = Object.entries(SS.SYNTH_PARAMS).map(([p, defs]) => `${p} {${Object.entries(defs).map(([k, d]) => `${k} ${d.min}-${d.max}`).join(", ")}}`).join("; ");

