import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const ROOT = path.resolve(__dirname, "..");
const SH = path.join(ROOT, "services/modbuilder/sheets");
const VERS = ["1.21.1", "1.21.4", "1.21.8", "1.21.11"];
type Member = { present: boolean; deprecated: boolean; removal: boolean; decls: string[] };
type Rec = { present: boolean; kind?: string; cancellable?: boolean; deprecated?: boolean; members?: Record<string, Member> };
type Fact = { id: string; group: string; class: string; members: string[]; say?: string; requires?: string[]; absentName?: string };
const FACTS: { version: string; facts: Fact[] } = JSON.parse(fs.readFileSync(path.join(SH, "api-facts.json"), "utf8"));
const VER: { factsVersion: string; method: string; versions: string[]; facts: Record<string, Record<string, Rec>>; packFormats: Record<string, { resource: number[]; data: number[] }> } =
  JSON.parse(fs.readFileSync(path.join(SH, "api-facts.verified.json"), "utf8"));
const sheet = (v: string) => fs.readFileSync(path.join(SH, `${v}.md`), "utf8");
const byId = new Map(FACTS.facts.map((f) => [f.id, f]));
const ok = (id: string, v: string): boolean => {
  const r = VER.facts[id][v];
  return r.present && Object.values(r.members ?? {}).every((m) => m.present) && (byId.get(id)!.requires ?? []).every((q) => ok(q, v));
};
const has = (id: string, v: string) => VER.facts[id][v].present;

describe("API facts: every fact was javap-checked on all four versions", () => {
  it("the verified file matches the definitions and covers every fact x version", () => {
    assert.equal(VER.factsVersion, FACTS.version);
