// Cyrus Minecraft coverage matrix (bundle mc-coverage): lib/cyrus/adapters/minecraft-coverage.json is well-formed, uses the
// planner lane vocabulary and the capability-catalogue v1 shape, agrees with the version registry and the golden corpus,
// and docs/cyrus/minecraft-coverage.md is fresh. Pure data checks. Run: tsx --test test/cyrus-mc-coverage.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { loadCoverage, loadResults, render, DOC_FILE } from "../scripts/cyrus/mc-coverage";
import { loadEvalSet, loadMatrix, laneOf } from "../lib/cyrus/eval/set";
import { COVERAGE_FIRST_RUN, planRun } from "../lib/cyrus/eval/run";
import { laneAccuracy, rulesSelector, scoreLanes } from "../lib/cyrus/eval/lanes";

const ROOT = path.join(__dirname, "..");
const cov = loadCoverage(ROOT);
const results = loadResults(ROOT);
const registry = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/versions/registry.json"), "utf8"));
const AVAIL = ["available", "limited", "unavailable"];
const GOLDEN = path.join(ROOT, "services/modbuilder/golden");
const cov0 = () => cov.archetypes;

describe("minecraft coverage matrix", () => {
  it("is a capability catalogue v1 for minecraft with every lane", () => {
    assert.equal(cov.schema, "cyrus.capabilities.v1");
    assert.equal(cov.game, "minecraft");
    const planner = cov.laneVocabulary.filter((l) => l !== "plugin");
    for (const l of planner) assert.ok(cov.lanes[l], `catalogue lane ${l}`);
    for (const [l, rule] of Object.entries(cov.lanes) as [string, { base: string; reason: string }][]) {
      assert.ok(planner.includes(l), `unknown lane ${l}`);
      assert.ok(AVAIL.includes(rule.base) && rule.reason.length > 10, l);
    }
  });

  it("has a per-version entry for every lane and version, with reasons and substitutes", () => {
    for (const lane of cov.laneVocabulary) for (const v of cov.versions) {
      const x = cov.versionLanes[lane]?.[v];
      assert.ok(x, `${lane} ${v}`);
      assert.ok(AVAIL.includes(x.availability), `${lane} ${v} availability`);
      assert.ok(x.reason.length > 10, `${lane} ${v} reason`);
      if (x.availability === "unavailable") assert.ok(x.substitute, `${lane} ${v}: unavailable needs a substitute`);
    }
