// Cyrus knowledge distillation S1-S2 (branch feature/cyrus-knowledge-distill, 2026-10-13): the failure rules mined from
// the eval first1 build outcomes (batch rules-2026-10-13.1) each have a failing and a passing fixture, the JDK wrong-package
// import is fixed without a model turn, `inject:false` keeps pre-check-only rules out of the prompt, and the whole
// knowledge growth (sheet batch 3 + rules) stays under 8 percent of the base system prompt per version.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/* eslint-disable @typescript-eslint/no-require-imports, @typescript-eslint/no-explicit-any */
const ROOT = path.resolve(__dirname, "..");
const PC = require("../services/modbuilder/precheck.js") as any;
const AF = require("../services/modbuilder/autofix.js") as any;
const PR = require("../services/modbuilder/prompts.js") as any;
const RULES = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/rules/failure-rules.json"), "utf8"));
const FIX = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-rules/rules-2026-10-13.1.json"), "utf8")).fixtures as Record<string, { version: string; fail: string; pass: string }>;
const BATCH = "rules-2026-10-13.1";

function files(src: string) {
  const d = fs.mkdtempSync(path.join(os.tmpdir(), "mb-dr-"));
  const rel = "src/main/java/dev/nxeon/plugins/demo/Sample.java";
  fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true });
  fs.writeFileSync(path.join(d, rel), src);
  return [{ rel, abs: path.join(d, rel) }];
}

describe("rules mined from the first1 build outcomes", () => {
  const batch = RULES.rules.filter((r: any) => r.batch === BATCH);
  it("the file version moved and the batch is complete", () => {
    assert.equal(RULES.version, BATCH);
    assert.equal(batch.length, 5);
    assert.deepEqual(Object.keys(FIX).sort(), batch.map((r: any) => r.id).sort());
    const ids = RULES.rules.map((r: any) => r.id);
    assert.equal(new Set(ids).size, ids.length, "rule ids are unique");
  });
  for (const id of Object.keys(FIX)) {
    it(`${id}: the failing fixture trips exactly this rule, the passing one trips none`, () => {
      const f = FIX[id];
      const r = RULES.rules.find((x: any) => x.id === id);
      assert.ok(r.pattern && r.fix && r.rule && r.source?.length, "pattern, fix, rule and source are required");
      assert.ok(r.versions.includes("*") || r.versions.includes(f.version));
      assert.deepEqual(PC.precheck(files(f.fail), f.version).map((h: any) => h.rule), [id]);
      assert.deepEqual(PC.precheck(files(f.pass), f.version), []);
      // every supported version sees it (the rules are version-independent: javap confirmed on all four)
      for (const v of ["1.21.1", "1.21.4", "1.21.8", "1.21.11"]) assert.deepEqual(PC.precheck(files(f.fail), v).map((h: any) => h.rule), [id], v);
    });
  }
  it("no earlier rule was removed or weakened (ids, patterns and versions unchanged)", () => {
    const before = JSON.parse(require("node:child_process").execFileSync("git", ["show", "ce6392c70d:services/modbuilder/rules/failure-rules.json"], { cwd: ROOT, encoding: "utf8", maxBuffer: 1 << 26 }));
    for (const old of before.rules) {
      const now = RULES.rules.find((x: any) => x.id === old.id);
      assert.ok(now, `${old.id} still exists`);
      for (const k of ["pattern", "unless", "versions", "warning", "scope", "rule", "fix"]) assert.deepEqual(now[k], old[k], `${old.id}.${k}`);
    }
  });
});

describe("JDK wrong-package imports are fixed without a model turn", () => {
  it("rewrites java.util.ThreadLocalRandom and friends, leaves right imports alone", () => {
    const src = "package dev.nxeon.plugins.demo;\nimport java.util.ThreadLocalRandom;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.Duration;\nimport java.util.List;\nclass Sample {}\n";
    const f = files(src);
    const r = AF.fixJdkImports(f);
    assert.deepEqual(r.fixes.map((x: any) => x.to), ["import java.util.concurrent.ThreadLocalRandom;", "import java.time.Duration;"]);
    const out = fs.readFileSync(f[0].abs, "utf8");
    assert.match(out, /^import java\.util\.concurrent\.ConcurrentHashMap;$/m);
    assert.match(out, /^import java\.util\.List;$/m);
    assert.deepEqual(PC.precheck(f, "1.21.11"), []);
  });
  it("fixImports runs the JDK fix even without a class index", () => {
    const f = files("package dev.nxeon.plugins.demo;\nimport java.util.AtomicInteger;\nclass Sample {}\n");
    const r = AF.fixImports(f, "1.21.11", { classIndex: () => null });
    assert.equal(r.fixes.length, 1);
  });
});

describe("prompt budget", () => {
  const BASE: Record<string, number> = { "1.21.1": 52014, "1.21.4": 53023, "1.21.8": 53236, "1.21.11": 55093 }; // chars at main ce6392c70d
  it("sheet batch 3 + rules grow the base system prompt by less than 8 percent on every version", () => {
    for (const v of Object.keys(BASE)) {
      const n = PR.systemPrompt(v).length;
      assert.ok(n <= BASE[v] * 1.08, `${v}: ${n} vs ${BASE[v]} = +${(((n - BASE[v]) / BASE[v]) * 100).toFixed(2)}%`);
      assert.ok(n >= BASE[v], v);
    }
  });
  it("a rule with inject:false is enforced by the pre-check but absent from the prompt", () => {
    const r = RULES.rules.find((x: any) => x.id === "getmaplist-wildcard-getordefault");
    assert.equal(r.inject, false);
    assert.ok(!PR.systemPrompt("1.21.11").includes(r.rule));
    assert.ok(PR.systemPrompt("1.21.11").includes(RULES.rules.find((x: any) => x.id === "bukkit-animals-plural").rule));
  });
  it("the design prompt states that a trigger is always an object (3 of 65 first1 builds wrote a bare string)", () => {
    assert.match(PR.DESIGN_SECTION, /trigger is ALWAYS an object with a type, never a bare string/);
    assert.doesNotMatch(PR.DESIGN_SECTION, /\| "sneak_right_click" \(same\)/);
  });
});
