package dev.nxeon.golden.blocklog;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden block log: remembers who broke or placed what, per chunk, in a BOUNDED ring buffer (the oldest entries are
 * dropped per chunk and globally), and can roll back one player's changes from the last N minutes in capped steps.
 * Logging runs at MONITOR priority after protections, so a cancelled change is never logged.
 */
public class BlockLog extends JavaPlugin implements Listener {
    record Entry(long at, UUID who, String name, int x, int y, int z, String before, String after) {}

    private final Map<String, Deque<Entry>> chunks = new HashMap<>();
    private int total;

    static String chunkKey(Block b) { return b.getWorld().getName() + ":" + b.getChunk().getChunkKey(); }

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("blocklog").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private void record(Player p, Block b, String before, String after) {
        Deque<Entry> q = chunks.computeIfAbsent(chunkKey(b), k -> new ArrayDeque<>());
        q.addLast(new Entry(System.currentTimeMillis(), p.getUniqueId(), p.getName(), b.getX(), b.getY(), b.getZ(), before, after));
        total++;
        int perChunk = Math.max(10, getConfig().getInt("max-per-chunk", 200));
        while (q.size() > perChunk) { q.removeFirst(); total--; }
        int cap = Math.max(100, getConfig().getInt("max-total", 20000));
        if (total > cap) {
            // drop the oldest entry of the fullest chunk until we are back under the global cap
            while (total > cap) {
                Deque<Entry> big = null;
                for (Deque<Entry> d : chunks.values()) if (big == null || d.size() > big.size()) big = d;
                if (big == null || big.isEmpty()) break;
                big.removeFirst();
                total--;
            }
        }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        record(e.getPlayer(), e.getBlock(), e.getBlock().getBlockData().getAsString(), "minecraft:air");
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onPlace(BlockPlaceEvent e) {
        record(e.getPlayer(), e.getBlock(), e.getBlockReplacedState().getBlockData().getAsString(), e.getBlock().getBlockData().getAsString());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) {
            sender.sendMessage(Component.text("GoldenBlockLog: " + total + " entries in " + chunks.size() + " chunks.", NamedTextColor.GREEN));
            return true;
        }
        if (args.length >= 1 && args[0].equalsIgnoreCase("rollback")) {
            if (args.length != 3) { p.sendMessage(Component.text("/blocklog rollback <player> <minutes>", NamedTextColor.RED)); return true; }
            long minutes;
            try { minutes = Long.parseLong(args[2]); } catch (NumberFormatException ex) { p.sendMessage(Component.text("Minutes must be a number.", NamedTextColor.RED)); return true; }
            Player target = Bukkit.getPlayerExact(args[1]);
            UUID who = target != null ? target.getUniqueId() : null;
            int limit = Math.max(1, getConfig().getInt("max-rollback-blocks", 256));
            long since = System.currentTimeMillis() - Math.max(1, Math.min(minutes, 1440)) * 60_000L;
            List<Entry> mine = new ArrayList<>();
            for (Deque<Entry> d : chunks.values()) for (Entry en : d) if (en.at() >= since && (who != null ? en.who().equals(who) : en.name().equalsIgnoreCase(args[1]))) mine.add(en);
            mine.sort((a, b) -> Long.compare(b.at(), a.at())); // newest first, so stacked changes unwind in order
            World w = p.getWorld();
            int done = 0;
            for (Entry en : mine) {
                if (done >= limit) break;
                Block b = w.getBlockAt(en.x(), en.y(), en.z());
                if (!b.getChunk().isLoaded()) continue;
                try {
                    BlockData old = Bukkit.createBlockData(en.before());
                    b.setBlockData(old, false);
                    done++;
                } catch (IllegalArgumentException ignored) { /* a block id this version no longer knows: skip it */ }
                Deque<Entry> q = chunks.get(chunkKey(b));
                if (q != null && q.remove(en)) total--;
            }
            p.sendMessage(Component.text("Rolled back " + done + " of " + mine.size() + " changes by " + args[1] + ".", NamedTextColor.YELLOW));
            return true;
        }
        Deque<Entry> q = chunks.get(chunkKey(p.getLocation().getBlock()));
        if (q == null || q.isEmpty()) { p.sendMessage(Component.text("Nothing logged in this chunk.", NamedTextColor.GRAY)); return true; }
        List<Entry> last = new ArrayList<>(q);
        int from = Math.max(0, last.size() - 8);
        for (Entry en : last.subList(from, last.size())) {
            long ago = (System.currentTimeMillis() - en.at()) / 1000;
            p.sendMessage(Component.text(en.name() + " " + (en.after().equals("minecraft:air") ? "broke" : "placed") + " at " + en.x() + " " + en.y() + " " + en.z() + " (" + ago + " s ago)", NamedTextColor.WHITE));
        }
        return true;
    }
}
E
echo ok

