package dev.nxeon.golden.veinminer;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.Tag;
import org.bukkit.block.Block;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden vein miner: breaking an ore or log while sneaking with a matching tool also breaks the connected blocks of the
 * same type, up to a hard cap per swing. Extra blocks go through Player#breakBlock (so claim/protection plugins and the
 * server's own drop rules apply), the tool wears like vanilla (ItemStack#damage) and the run stops when it breaks.
 */
public class Vein extends JavaPlugin implements Listener {
    private final Set<UUID> busy = new HashSet<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("vein").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    static boolean veinBlock(Material m) {
        return Tag.COAL_ORES.isTagged(m) || Tag.IRON_ORES.isTagged(m) || Tag.COPPER_ORES.isTagged(m) || Tag.GOLD_ORES.isTagged(m)
            || Tag.DIAMOND_ORES.isTagged(m) || Tag.EMERALD_ORES.isTagged(m) || Tag.REDSTONE_ORES.isTagged(m) || Tag.LAPIS_ORES.isTagged(m)
            || Tag.LOGS.isTagged(m);
    }

    static boolean rightTool(Material block, ItemStack tool) {
        String n = tool.getType().name();
        return Tag.LOGS.isTagged(block) ? n.endsWith("_AXE") : n.endsWith("_PICKAXE");
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        Player p = e.getPlayer();
        if (busy.contains(p.getUniqueId())) return; // our own breakBlock calls come back through this event
        if (getConfig().getBoolean("require-sneak", true) && !p.isSneaking()) return;
        if (!p.hasPermission("goldenvein.use")) return;
        Block origin = e.getBlock();
        ItemStack tool = p.getInventory().getItemInMainHand();
        if (!veinBlock(origin.getType()) || !rightTool(origin.getType(), tool)) return;
        int cap = Math.max(1, Math.min(getConfig().getInt("max-blocks", 32), 64));
        List<Block> found = new ArrayList<>();
        Set<Block> seen = new HashSet<>();
        ArrayDeque<Block> queue = new ArrayDeque<>();
        queue.add(origin);
        seen.add(origin);
        while (!queue.isEmpty() && found.size() < cap) {
            Block b = queue.poll();
            for (int dx = -1; dx <= 1; dx++) for (int dy = -1; dy <= 1; dy++) for (int dz = -1; dz <= 1; dz++) {
                if (dx == 0 && dy == 0 && dz == 0) continue;
                Block n = b.getRelative(dx, dy, dz);
                if (n.getType() != origin.getType() || !seen.add(n)) continue;
                if (found.size() >= cap - 1) break;
                found.add(n);
                queue.add(n);
            }
        }
        boolean wear = getConfig().getBoolean("wear-per-block", true);
        busy.add(p.getUniqueId());
        try {
            for (Block b : found) {
                if (b.getType() != origin.getType()) continue;
                if (!p.breakBlock(b)) continue;
                if (wear) {
                    ItemStack now = p.getInventory().getItemInMainHand().damage(1, p);
                    p.getInventory().setItemInMainHand(now);
                    if (now.isEmpty() || !rightTool(origin.getType(), now)) break; // the tool broke: stop here
                }
            }
        } finally {
            busy.remove(p.getUniqueId());
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(Component.text("GoldenVein: up to " + getConfig().getInt("max-blocks", 32) + " blocks per swing, sneak required "
            + getConfig().getBoolean("require-sneak", true) + ".", NamedTextColor.GREEN));
        return true;
    }
}
