package dev.nxeon.golden.mobcatcher;

import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.block.Block;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Boss;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntitySnapshot;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.event.Event;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.player.PlayerInteractEntityEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden mob catcher: right-click a mob with a Mob Net to turn it into a "caught mob" item that keeps the whole entity
 * (name, health, villager trades, armour...) as an EntitySnapshot string in the item's PersistentDataContainer; right-click
 * a block with that item to release an exact copy. Vanilla bosses (the Boss interface), players and a config list are refused.
 */
public class MobNet extends JavaPlugin implements Listener {
    private NamespacedKey netKey;
    private NamespacedKey caughtKey;
    private int caught;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        netKey = new NamespacedKey(this, "net");
        caughtKey = new NamespacedKey(this, "caught");
        getCommand("mobnet").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private ItemStack net() {
        ItemStack it = new ItemStack(Material.LEAD);
        it.editMeta(m -> {
            m.displayName(Component.text("Mob Net", NamedTextColor.AQUA).decoration(TextDecoration.ITALIC, false));
            m.lore(List.of(Component.text("Right-click a mob to catch it.", NamedTextColor.GRAY)));
            m.getPersistentDataContainer().set(netKey, PersistentDataType.BOOLEAN, true);
        });
        return it;
    }

    private boolean isNet(ItemStack it) {
        return it != null && !it.isEmpty() && it.hasItemMeta() && it.getItemMeta().getPersistentDataContainer().has(netKey, PersistentDataType.BOOLEAN);
    }

    private boolean refused(Entity e) {
        if (!(e instanceof LivingEntity) || e instanceof Player || e instanceof Boss) return true;
        return getConfig().getStringList("blocked-types").contains(e.getType().name());
    }

    @EventHandler
    public void onCatch(PlayerInteractEntityEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        Player p = e.getPlayer();
        ItemStack hand = p.getInventory().getItemInMainHand();
        if (!isNet(hand)) return;
        e.setCancelled(true);
        Entity target = e.getRightClicked();
        if (refused(target)) { p.sendActionBar(Component.text("That cannot be caught.", NamedTextColor.RED)); return; }
        EntitySnapshot snap = target.createSnapshot();
        if (snap == null) { p.sendActionBar(Component.text("That cannot be caught.", NamedTextColor.RED)); return; }
        String data = snap.getAsString();
        ItemStack out = new ItemStack(Material.EGG);
        String type = target.getType().name().toLowerCase().replace('_', ' ');
        out.editMeta(m -> {
            m.displayName(Component.text("Caught " + type, NamedTextColor.GOLD).decoration(TextDecoration.ITALIC, false));
            m.getPersistentDataContainer().set(caughtKey, PersistentDataType.STRING, data);
        });
        target.remove();
        caught++;
        if (!getConfig().getBoolean("reusable-net", false)) hand.setAmount(hand.getAmount() - 1);
        p.getInventory().addItem(out).values().forEach(left -> p.getWorld().dropItemNaturally(p.getLocation(), left));
        p.sendActionBar(Component.text("Caught a " + type + ".", NamedTextColor.GREEN));
    }

    @EventHandler
    public void onRelease(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND || e.getAction() != Action.RIGHT_CLICK_BLOCK || e.useInteractedBlock() == Event.Result.DENY) return;
        ItemStack hand = e.getPlayer().getInventory().getItemInMainHand();
        if (hand.isEmpty() || !hand.hasItemMeta()) return;
        String data = hand.getItemMeta().getPersistentDataContainer().get(caughtKey, PersistentDataType.STRING);
        if (data == null) return;
        e.setCancelled(true);
        Block at = e.getClickedBlock();
        if (at == null) return;
        Location where = at.getRelative(e.getBlockFace()).getLocation().add(0.5, 0, 0.5);
        try {
            EntitySnapshot snap = Bukkit.getEntityFactory().createEntitySnapshot(data);
            Entity spawned = snap.createEntity(where);
            if (spawned == null) { e.getPlayer().sendActionBar(Component.text("It would not come out.", NamedTextColor.RED)); return; }
        } catch (IllegalArgumentException ex) {
            e.getPlayer().sendActionBar(Component.text("This catch is broken.", NamedTextColor.RED));
            return;
        }
        hand.setAmount(hand.getAmount() - 1);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (sender instanceof Player p && args.length == 1 && args[0].equalsIgnoreCase("give")) {
            p.getInventory().addItem(net());
            p.sendMessage(Component.text("Here is a Mob Net.", NamedTextColor.GREEN));
            return true;
        }
        sender.sendMessage(Component.text("GoldenMobNet: " + caught + " mobs caught.", NamedTextColor.GREEN));
        return true;
    }
}
