package dev.nxeon.golden.leaderboard;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.Statistic;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden top lists: /top <kills|deaths|mobs|walked> from the vanilla statistics (OfflinePlayer#getStatistic), cached and
 * refreshed on a timer so a command never scans players. The scan is capped (max-players) and sorted once per refresh.
 */
public class Top extends JavaPlugin {
    enum Board {
        KILLS("kills", Statistic.PLAYER_KILLS, 1), DEATHS("deaths", Statistic.DEATHS, 1), MOBS("mobs", Statistic.MOB_KILLS, 1), WALKED("walked", Statistic.WALK_ONE_CM, 100_000);
        final String id; final Statistic stat; final int divisor;
        Board(String id, Statistic stat, int divisor) { this.id = id; this.stat = stat; this.divisor = divisor; }
    }
    record Row(String name, int value) {}

    private final Map<Board, List<Row>> cache = new EnumMap<>(Board.class);

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("top").setExecutor(this);
        long every = Math.max(10, getConfig().getLong("refresh-seconds", 60)) * 20L;
        getServer().getScheduler().runTaskTimer(this, this::refresh, 20L, every);
        refresh();
    }

    private void refresh() {
        int cap = Math.max(1, getConfig().getInt("max-players", 500));
        int rows = Math.max(1, Math.min(getConfig().getInt("rows", 5), 15));
        OfflinePlayer[] all = Bukkit.getOfflinePlayers();
        int n = Math.min(all.length, cap);
        for (Board b : Board.values()) {
            List<Row> list = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                OfflinePlayer p = all[i];
                if (p.getName() == null) continue;
                int v = p.getStatistic(b.stat) / b.divisor;
                if (v > 0) list.add(new Row(p.getName(), v));
            }
            list.sort(Comparator.comparingInt(Row::value).reversed());
            cache.put(b, new ArrayList<>(list.subList(0, Math.min(rows, list.size()))));
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        Board board = null;
        if (args.length >= 1) for (Board b : Board.values()) if (b.id.equalsIgnoreCase(args[0])) board = b;
        if (board == null) { sender.sendMessage(Component.text("Use /top kills, deaths, mobs or walked.", NamedTextColor.RED)); return true; }
        List<Row> rows = cache.getOrDefault(board, List.of());
        StringBuilder sb = new StringBuilder("GoldenTop " + board.id + ":");
        if (rows.isEmpty()) sb.append(" nobody yet.");
        for (int i = 0; i < rows.size(); i++) sb.append(' ').append(i + 1).append(". ").append(rows.get(i).name()).append(' ').append(rows.get(i).value());
        sender.sendMessage(Component.text(sb.toString(), NamedTextColor.GOLD));
        return true;
    }
}
