package dev.nxeon.golden.crops;

import java.util.concurrent.ThreadLocalRandom;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.block.Block;
import org.bukkit.block.BlockState;
import org.bukkit.block.data.Ageable;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockGrowEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden crop tweaks on VANILLA crops (no new blocks: those need a client mod): a natural growth step can jump one extra
 * stage (BlockGrowEvent#getNewState is the state about to be placed, so we edit it in place) and a fully grown crop broken by
 * a player can drop one more copy of its produce. Both chances are config values; nothing runs on a timer.
 */
public class Crops extends JavaPlugin implements Listener {
    private int bonusStages;
    private int bonusHarvests;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("crops").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private double chance(String path, double def) { return Math.max(0, Math.min(1, getConfig().getDouble(path, def))); }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onGrow(BlockGrowEvent e) {
        BlockState next = e.getNewState();
        if (!(next.getBlockData() instanceof Ageable age) || age.getAge() >= age.getMaximumAge()) return;
        if (ThreadLocalRandom.current().nextDouble() >= chance("growth-bonus-chance", 0.25)) return;
        age.setAge(age.getAge() + 1);
        next.setBlockData(age);
        bonusStages++;
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        Block b = e.getBlock();
        if (!(b.getBlockData() instanceof Ageable age) || age.getAge() < age.getMaximumAge()) return;
        if (ThreadLocalRandom.current().nextDouble() >= chance("harvest-bonus-chance", 0.2)) return;
        ItemStack tool = e.getPlayer().getInventory().getItemInMainHand();
        for (ItemStack drop : b.getDrops(tool, e.getPlayer())) {
            // the seed item comes back as seed; the produce (a different material) is what we double
            if (drop.getType().name().endsWith("_SEEDS") || drop.getType() == b.getType()) continue;
            b.getWorld().dropItemNaturally(b.getLocation().add(0.5, 0.2, 0.5), drop.asOne());
            bonusHarvests++;
            break;
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(Component.text("GoldenCrops: growth bonus " + Math.round(chance("growth-bonus-chance", 0.25) * 100) + "%, harvest bonus "
            + Math.round(chance("harvest-bonus-chance", 0.2) * 100) + "%, " + bonusStages + " bonus stages, " + bonusHarvests + " bonus harvests.", NamedTextColor.GREEN));
        return true;
    }
}
