package dev.nxeon.golden.auction;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryDragEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryHolder;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden auction house without an economy plugin: prices are counts of a currency item. A listing takes the item out of the
 * seller's hand (escrow: stored as ItemStack bytes in auctions.yml, so enchants/meta survive), a buyer pays the currency
 * from the inventory, and the seller's payout waits in a claim box (/ah claim) so nothing is lost when they are offline.
 * Expired listings go back to the seller's claim box too. The menu is an InventoryHolder, never matched by title.
 */
public class Auction extends JavaPlugin implements Listener {
    record Listing(int id, UUID seller, String sellerName, int price, long expires, ItemStack item) {}

    static class Menu implements InventoryHolder {
        final Inventory inv = Bukkit.createInventory(this, 54, Component.text("Auction house"));
        final List<Integer> ids = new ArrayList<>();
        @Override public Inventory getInventory() { return inv; }
    }

    private final Map<Integer, Listing> listings = new LinkedHashMap<>();
    private final Map<UUID, Integer> payouts = new HashMap<>();
    private final Map<UUID, List<ItemStack>> returned = new HashMap<>();
    private int nextId = 1;
    private File file;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "auctions.yml");
        load();
        getCommand("ah").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::expire, 1200L, 1200L);
    }

    @Override
    public void onDisable() { save(); }

    private Material currency() {
        Material m = Material.matchMaterial(getConfig().getString("currency", "DIAMOND"));
        return m == null || m.isAir() ? Material.DIAMOND : m;
    }

    private void load() {
        YamlConfiguration y = YamlConfiguration.loadConfiguration(file);
        nextId = y.getInt("next-id", 1);
        for (String k : y.getConfigurationSection("listings") == null ? List.<String>of() : new ArrayList<>(y.getConfigurationSection("listings").getKeys(false))) {
            String p = "listings." + k + ".";
            try {
                ItemStack it = ItemStack.deserializeBytes(Base64.getDecoder().decode(y.getString(p + "item", "")));
                listings.put(Integer.parseInt(k), new Listing(Integer.parseInt(k), UUID.fromString(y.getString(p + "seller")), y.getString(p + "name", "?"), y.getInt(p + "price"), y.getLong(p + "expires"), it));
            } catch (IllegalArgumentException ex) { getLogger().warning("Skipped a broken listing " + k); }
        }
        if (y.getConfigurationSection("payouts") != null) for (String k : y.getConfigurationSection("payouts").getKeys(false)) payouts.put(UUID.fromString(k), y.getInt("payouts." + k));
    }

    private void save() {
        YamlConfiguration y = new YamlConfiguration();
        y.set("next-id", nextId);
        for (Listing l : listings.values()) {
            String p = "listings." + l.id() + ".";
            y.set(p + "seller", l.seller().toString());
            y.set(p + "name", l.sellerName());
            y.set(p + "price", l.price());
            y.set(p + "expires", l.expires());
            y.set(p + "item", Base64.getEncoder().encodeToString(l.item().serializeAsBytes()));
        }
        payouts.forEach((u, n) -> y.set("payouts." + u, n));
        try { y.save(file); } catch (IOException e) { getLogger().warning(e.getMessage()); }
    }

    private void expire() {
        long now = System.currentTimeMillis();
        Iterator<Listing> it = listings.values().iterator();
        while (it.hasNext()) {
            Listing l = it.next();
            if (l.expires() > now) continue;
            it.remove();
            returned.computeIfAbsent(l.seller(), k -> new ArrayList<>()).add(l.item());
        }
    }

    private void give(Player p, ItemStack item) {
        p.getInventory().addItem(item).values().forEach(left -> p.getWorld().dropItemNaturally(p.getLocation(), left));
    }

    private void open(Player p) {
        Menu m = new Menu();
        int slot = 0;
        for (Listing l : listings.values()) {
            if (slot >= 45) break;
            ItemStack shown = l.item().clone();
            List<Component> lore = new ArrayList<>(shown.lore() == null ? List.<Component>of() : shown.lore());
