 * from the inventory, and the seller's payout waits in a claim box (/ah claim) so nothing is lost when they are offline.
 * Expired listings go back to the seller's claim box too. The menu is an InventoryHolder, never matched by title.
 */
public class Auction extends JavaPlugin implements Listener {
    record Listing(int id, UUID seller, String sellerName, int price, long expires, ItemStack item) {}

    static class Menu implements InventoryHolder {
        final Inventory inv = Bukkit.createInventory(this, 54, Component.text("Auction house"));
        final List<Integer> ids = new ArrayList<>();
        @Override public Inventory getInventory() { return inv; }
    }

    private final Map<Integer, Listing> listings = new LinkedHashMap<>();
    private final Map<UUID, Integer> payouts = new HashMap<>();
    private final Map<UUID, List<ItemStack>> returned = new HashMap<>();
    private int nextId = 1;
    private File file;

