        saveDefaultConfig();
        file = new File(getDataFolder(), "auctions.yml");
        load();
        getCommand("ah").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::expire, 1200L, 1200L);
    }

    @Override
    public void onDisable() { save(); }

    private Material currency() {
        Material m = Material.matchMaterial(getConfig().getString("currency", "DIAMOND"));
        return m == null || m.isAir() ? Material.DIAMOND : m;
    }

    private void load() {
        YamlConfiguration y = YamlConfiguration.loadConfiguration(file);
        nextId = y.getInt("next-id", 1);
        for (String k : y.getConfigurationSection("listings") == null ? List.<String>of() : new ArrayList<>(y.getConfigurationSection("listings").getKeys(false))) {
            String p = "listings." + k + ".";
            try {
                ItemStack it = ItemStack.deserializeBytes(Base64.getDecoder().decode(y.getString(p + "item", "")));
                listings.put(Integer.parseInt(k), new Listing(Integer.parseInt(k), UUID.fromString(y.getString(p + "seller")), y.getString(p + "name", "?"), y.getInt(p + "price"), y.getLong(p + "expires"), it));
            } catch (IllegalArgumentException ex) { getLogger().warning("Skipped a broken listing " + k); }
        }
        if (y.getConfigurationSection("payouts") != null) for (String k : y.getConfigurationSection("payouts").getKeys(false)) payouts.put(UUID.fromString(k), y.getInt("payouts." + k));
    }

    private void save() {
        YamlConfiguration y = new YamlConfiguration();
        y.set("next-id", nextId);
        for (Listing l : listings.values()) {
            String p = "listings." + l.id() + ".";
            y.set(p + "seller", l.seller().toString());
            y.set(p + "name", l.sellerName());
            y.set(p + "price", l.price());
            y.set(p + "expires", l.expires());
            y.set(p + "item", Base64.getEncoder().encodeToString(l.item().serializeAsBytes()));
        }
        payouts.forEach((u, n) -> y.set("payouts." + u, n));
        try { y.save(file); } catch (IOException e) { getLogger().warning(e.getMessage()); }
    }

    private void expire() {
        long now = System.currentTimeMillis();
        Iterator<Listing> it = listings.values().iterator();
        while (it.hasNext()) {
            Listing l = it.next();
            if (l.expires() > now) continue;
            it.remove();
            returned.computeIfAbsent(l.seller(), k -> new ArrayList<>()).add(l.item());
        }
    }

    private void give(Player p, ItemStack item) {
