    }

    private void open(Player p) {
        Menu m = new Menu();
        int slot = 0;
        for (Listing l : listings.values()) {
            if (slot >= 45) break;
            ItemStack shown = l.item().clone();
            List<Component> lore = new ArrayList<>(shown.lore() == null ? List.<Component>of() : shown.lore());
            lore.add(Component.text("Price: " + l.price() + " " + currency().name().toLowerCase(), NamedTextColor.GOLD).decoration(TextDecoration.ITALIC, false));
            lore.add(Component.text("Seller: " + l.sellerName(), NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false));
            shown.lore(lore);
            m.inv.setItem(slot, shown);
            m.ids.add(l.id());
            slot++;
        }
        p.openInventory(m.inv);
    }

    @EventHandler
    public void onClick(InventoryClickEvent e) {
        if (!(e.getInventory().getHolder(false) instanceof Menu menu)) return;
        e.setCancelled(true);
        if (!(e.getWhoClicked() instanceof Player p) || e.getRawSlot() < 0 || e.getRawSlot() >= menu.ids.size()) return;
        Listing l = listings.get(menu.ids.get(e.getRawSlot()));
