        int fee = l.price() * Math.max(0, Math.min(getConfig().getInt("fee-percent", 5), 100)) / 100;
        payouts.merge(l.seller(), l.price() - fee, Integer::sum);
        give(p, l.item());
        p.sendMessage(Component.text("Bought for " + l.price() + ".", NamedTextColor.GREEN));
        p.closeInventory();
        save();
    }

    @EventHandler
    public void onDrag(InventoryDragEvent e) {
        if (e.getInventory().getHolder(false) instanceof Menu) e.setCancelled(true);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) {
            int unclaimed = payouts.values().stream().mapToInt(Integer::intValue).sum();
            sender.sendMessage(Component.text("GoldenAuction: " + listings.size() + " listings, " + unclaimed + " unclaimed payouts, currency " + currency().name() + ".", NamedTextColor.GREEN));
            return true;
        }
        if (args.length == 0) { open(p); return true; }
        if (args[0].equalsIgnoreCase("claim")) {
            int money = payouts.getOrDefault(p.getUniqueId(), 0);
            List<ItemStack> back = returned.remove(p.getUniqueId());
            if (money <= 0 && (back == null || back.isEmpty())) { p.sendMessage(Component.text("Nothing to claim.", NamedTextColor.GRAY)); return true; }
            payouts.remove(p.getUniqueId());
            if (money > 0) give(p, new ItemStack(currency(), money));
            if (back != null) back.forEach(i -> give(p, i));
            p.sendMessage(Component.text("Claimed " + money + " " + currency().name().toLowerCase() + (back == null ? "" : " and " + back.size() + " returned items") + ".", NamedTextColor.GREEN));
            save();
            return true;
        }
        if (args[0].equalsIgnoreCase("sell") && args.length == 2) {
            int price;
            try { price = Integer.parseInt(args[1]); } catch (NumberFormatException ex) { p.sendMessage(Component.text("The price must be a whole number.", NamedTextColor.RED)); return true; }
            if (price < 1 || price > 100000) { p.sendMessage(Component.text("Price 1-100000.", NamedTextColor.RED)); return true; }
            ItemStack hand = p.getInventory().getItemInMainHand();
            if (hand.isEmpty()) { p.sendMessage(Component.text("Hold the item to sell.", NamedTextColor.RED)); return true; }
            long mine = listings.values().stream().filter(l -> l.seller().equals(p.getUniqueId())).count();
            if (mine >= Math.max(1, getConfig().getInt("max-listings-per-player", 5))) { p.sendMessage(Component.text("You have too many listings.", NamedTextColor.RED)); return true; }
            long hours = Math.max(1, getConfig().getLong("listing-hours", 48));
            int id = nextId++;
            listings.put(id, new Listing(id, p.getUniqueId(), p.getName(), price, System.currentTimeMillis() + hours * 3_600_000L, hand.clone()));
            p.getInventory().setItemInMainHand(null);
