package dev.nxeon.golden.movecheck;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.GameMode;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.player.PlayerTeleportEvent;
import org.bukkit.event.player.PlayerVelocityEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.potion.PotionEffectType;

/**
 * Golden movement checks. Honest scope: two heuristics (too fast per tick, hovering in the air) on the SERVER's view of
 * movement; they catch crude speed/fly hacks, not reach, killaura or packet tricks. The usual false-positive sources are
 * exempted (creative/spectator, flying allowed, gliding, riding, riptide, speed/jump potions, recent knockback, velocity or
 * teleport grace period). Violations alert staff and, after a few, set the player back to the last good position.
 */
public class MoveCheck extends JavaPlugin implements Listener {
    static final class State {
        Location lastGood;
        long grace;       // millis timestamp until which nothing is checked
        int hover;
        int alerts;
    }
    private final Map<UUID, State> states = new HashMap<>();
    private int totalAlerts;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("movecheck").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private State st(Player p) { return states.computeIfAbsent(p.getUniqueId(), k -> new State()); }

    private boolean exempt(Player p) {
        GameMode g = p.getGameMode();
        return g == GameMode.CREATIVE || g == GameMode.SPECTATOR || p.getAllowFlight() || p.isGliding() || p.isInsideVehicle()
            || p.isRiptiding() || p.hasPermission("goldenmove.exempt") || p.hasPotionEffect(PotionEffectType.LEVITATION)
            || p.hasPotionEffect(PotionEffectType.SLOW_FALLING);
    }

    private void grace(Player p, long ms) { st(p).grace = System.currentTimeMillis() + ms; }

    @EventHandler public void onTeleport(PlayerTeleportEvent e) { grace(e.getPlayer(), 2000); }
    @EventHandler public void onVelocity(PlayerVelocityEvent e) { grace(e.getPlayer(), 1500); }
    @EventHandler public void onDamage(EntityDamageEvent e) { if (e.getEntity() instanceof Player p) grace(p, 1500); }
    @EventHandler public void onQuit(PlayerQuitEvent e) { states.remove(e.getPlayer().getUniqueId()); }

    private static boolean solidBelow(Location l) {
        Block b = l.getBlock();
        for (int i = 1; i <= 3; i++) {
            Material m = b.getRelative(0, -i, 0).getType();
            if (!m.isAir() && (m.isSolid() || m == Material.WATER || m == Material.LAVA || m == Material.LADDER || m == Material.VINE || m == Material.COBWEB)) return true;
        }
        return false;
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (!e.hasChangedPosition()) return;
        Player p = e.getPlayer();
        State s = st(p);
        Location from = e.getFrom(), to = e.getTo();
        if (exempt(p) || System.currentTimeMillis() < s.grace || from.getWorld() != to.getWorld()) { s.hover = 0; s.lastGood = to.clone(); return; }
        double dx = to.getX() - from.getX(), dz = to.getZ() - from.getZ();
        double speed = Math.sqrt(dx * dx + dz * dz);
        double cap = getConfig().getDouble("max-horizontal-per-tick", 0.9);
        var swift = p.getPotionEffect(PotionEffectType.SPEED);
        if (swift != null) cap *= 1 + 0.2 * (swift.getAmplifier() + 1);
        boolean bad = false;
        String why = "";
        if (speed > cap) { bad = true; why = "speed " + String.format("%.2f", speed) + " b/tick"; }
        if (!solidBelow(to) && to.getY() >= from.getY() - 0.001) s.hover++; else s.hover = 0;
        if (s.hover > getConfig().getInt("max-hover-steps", 25)) { bad = true; why = "hover " + s.hover + " steps"; s.hover = 0; }
        if (!bad) { s.lastGood = to.clone(); return; }
        s.alerts++;
        totalAlerts++;
        Component msg = Component.text("[GoldenMoveCheck] " + p.getName() + ": " + why + " (alert " + s.alerts + ")", NamedTextColor.RED);
        for (Player staff : getServer().getOnlinePlayers()) if (staff.hasPermission("goldenmove.notify")) staff.sendMessage(msg);
        getLogger().info(p.getName() + ": " + why);
        if (s.alerts >= Math.max(1, getConfig().getInt("setback-after", 3)) && s.lastGood != null) {
            e.setTo(s.lastGood);
            grace(p, 1000);
            s.alerts = 0;
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(Component.text("GoldenMoveCheck: " + totalAlerts + " alerts, " + states.size() + " players tracked.", NamedTextColor.GREEN));
        return true;
    }
}
