package dev.nxeon.golden.duels;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.attribute.Attribute;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.player.PlayerRespawnEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden 1v1 duels: /duel <player> challenges, /duel accept starts it. Fighters keep their inventory (nothing drops, no
 * XP loss), are teleported to a spot beside the challenger and are sent back to where they were when it ends (death, quit
 * or /duel leave). Damage from outside the duel is cancelled for both fighters, and a duel never starts with a player who
 * is already in one.
 */
public class Duels extends JavaPlugin implements Listener {
    record Duel(UUID a, UUID b, Location backA, Location backB) {}

    private final Map<UUID, UUID> challenges = new HashMap<>(); // target -> challenger
    private final Map<UUID, Duel> duels = new HashMap<>();      // either fighter -> the duel
    private final Map<UUID, Location> returnAfterRespawn = new HashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("duel").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private void end(Duel d, Player winner) {
        duels.remove(d.a());
        duels.remove(d.b());
        for (UUID id : new UUID[] {d.a(), d.b()}) {
            Player p = Bukkit.getPlayer(id);
            Location back = id.equals(d.a()) ? d.backA() : d.backB();
            if (p == null || back == null) continue;
            if (p.isDead()) { returnAfterRespawn.put(id, back); continue; }
            p.teleport(back);
        }
        if (winner != null) {
            if (getConfig().getBoolean("heal-winner", true)) {
                var max = winner.getAttribute(Attribute.MAX_HEALTH);
                winner.setHealth(max == null ? 20.0 : Math.min(max.getValue(), 40.0));
                winner.setFoodLevel(20);
            }
            Bukkit.broadcast(Component.text(winner.getName() + " won the duel.", NamedTextColor.GOLD));
        }
    }

    @EventHandler
    public void onDeath(PlayerDeathEvent e) {
        Duel d = duels.get(e.getEntity().getUniqueId());
        if (d == null) return;
        e.setKeepInventory(true);
        e.setKeepLevel(true);
        e.getDrops().clear();
        e.setDroppedExp(0);
        UUID other = d.a().equals(e.getEntity().getUniqueId()) ? d.b() : d.a();
        end(d, Bukkit.getPlayer(other));
    }

    @EventHandler
    public void onRespawn(PlayerRespawnEvent e) {
        Location back = returnAfterRespawn.remove(e.getPlayer().getUniqueId());
        if (back != null) e.setRespawnLocation(back);
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        UUID id = e.getPlayer().getUniqueId();
        challenges.remove(id);
        challenges.values().remove(id);
        Duel d = duels.get(id);
        if (d == null) return;
        UUID other = d.a().equals(id) ? d.b() : d.a();
        Location mine = id.equals(d.a()) ? d.backA() : d.backB();
        e.getPlayer().teleport(mine); // they log out where they started, not in the arena
        end(d, Bukkit.getPlayer(other));
    }

    @EventHandler
    public void onHit(EntityDamageByEntityEvent e) {
        if (!(e.getEntity() instanceof Player victim)) return;
        Duel vd = duels.get(victim.getUniqueId());
        Player attacker = e.getDamageSource().getCausingEntity() instanceof Player p ? p : null;
        Duel ad = attacker == null ? null : duels.get(attacker.getUniqueId());
        if (vd == null && ad == null) return;
        if (vd != ad) e.setCancelled(true); // a bystander and a fighter never hurt each other
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) {
            sender.sendMessage(Component.text("GoldenDuels: " + duels.size() / 2 + " active duels, " + challenges.size() + " pending challenges.", NamedTextColor.GREEN));
            return true;
        }
        if (args.length == 1 && args[0].equalsIgnoreCase("leave")) {
            Duel d = duels.get(p.getUniqueId());
            if (d == null) { p.sendMessage(Component.text("You are not in a duel.", NamedTextColor.RED)); return true; }
            UUID other = d.a().equals(p.getUniqueId()) ? d.b() : d.a();
            end(d, Bukkit.getPlayer(other));
            return true;
        }
        if (args.length == 1 && args[0].equalsIgnoreCase("accept")) {
            UUID from = challenges.remove(p.getUniqueId());
            Player challenger = from == null ? null : Bukkit.getPlayer(from);
            if (challenger == null) { p.sendMessage(Component.text("Nobody challenged you.", NamedTextColor.RED)); return true; }
            if (duels.containsKey(from) || duels.containsKey(p.getUniqueId())) { p.sendMessage(Component.text("One of you is already in a duel.", NamedTextColor.RED)); return true; }
            Location base = challenger.getLocation();
            Location spot = base.clone().add(getConfig().getDouble("arena-offset-x", 12), 0, getConfig().getDouble("arena-offset-z", 0));
            spot.setY(base.getWorld().getHighestBlockYAt(spot) + 1);
            Duel d = new Duel(from, p.getUniqueId(), challenger.getLocation(), p.getLocation());
            duels.put(from, d);
            duels.put(p.getUniqueId(), d);
            p.teleport(spot);
            challenger.sendMessage(Component.text("Duel started against " + p.getName() + "!", NamedTextColor.GOLD));
            p.sendMessage(Component.text("Duel started against " + challenger.getName() + "!", NamedTextColor.GOLD));
            return true;
        }
        if (args.length != 1) { p.sendMessage(Component.text("/duel <player>, /duel accept, /duel leave", NamedTextColor.RED)); return true; }
        Player target = Bukkit.getPlayerExact(args[0]);
        if (target == null || target.equals(p)) { p.sendMessage(Component.text("Name an online player other than yourself.", NamedTextColor.RED)); return true; }
        if (duels.containsKey(p.getUniqueId()) || duels.containsKey(target.getUniqueId())) { p.sendMessage(Component.text("One of you is already in a duel.", NamedTextColor.RED)); return true; }
        challenges.put(target.getUniqueId(), p.getUniqueId());
        target.sendMessage(Component.text(p.getName() + " challenges you: /duel accept", NamedTextColor.GOLD));
        p.sendMessage(Component.text("Challenge sent to " + target.getName() + ".", NamedTextColor.GREEN));
        long secs = Math.max(5, getConfig().getLong("challenge-seconds", 30));
        getServer().getScheduler().runTaskLater(this, () -> challenges.remove(target.getUniqueId(), p.getUniqueId()), secs * 20L);
        return true;
    }
}
