package dev.nxeon.golden.chestshop;

import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.block.Container;
import org.bukkit.block.Sign;
import org.bukkit.block.data.Directional;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.SignChangeEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden sign shops: put a wall sign on a chest, line 1 "[Shop]", line 2 the price in the currency item. The owner and
 * price are stored on the sign's PersistentDataContainer. Right-click the sign to buy ONE of the chest's first item: the
 * price moves into the chest, the item to the buyer, atomically (a full chest refuses the sale). Only the owner (or an
 * admin) can break the sign or the chest it serves.
 */
public class ChestShop extends JavaPlugin implements Listener {
    private NamespacedKey ownerKey;
    private NamespacedKey priceKey;
    private int sales;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        ownerKey = new NamespacedKey(this, "owner");
        priceKey = new NamespacedKey(this, "price");
        getCommand("chestshop").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private Material currency() {
        Material m = Material.matchMaterial(getConfig().getString("currency", "EMERALD"));
        return m == null || m.isAir() ? Material.EMERALD : m;
    }

    private static String plain(Component c) { return PlainTextComponentSerializer.plainText().serialize(c).trim(); }

    /** The container a wall sign is mounted on, or null. */
    private static Block chestBehind(Block signBlock) {
        if (!(signBlock.getBlockData() instanceof Directional d)) return null;
        Block behind = signBlock.getRelative(d.getFacing().getOppositeFace());
        return behind.getState(false) instanceof Container ? behind : null;
    }

    @EventHandler
    public void onSign(SignChangeEvent e) {
        if (!plain(e.line(0) == null ? Component.empty() : e.line(0)).equalsIgnoreCase("[Shop]")) return;
        Player p = e.getPlayer();
        Block chest = chestBehind(e.getBlock());
        int price;
        try { price = Integer.parseInt(plain(e.line(1) == null ? Component.empty() : e.line(1))); } catch (NumberFormatException ex) { price = -1; }
        if (chest == null || price < 1 || price > getConfig().getInt("max-price", 1000)) {
            e.setCancelled(true);
            p.sendMessage(Component.text("A shop needs a wall sign on a chest and a whole-number price on line 2.", NamedTextColor.RED));
            return;
        }
        if (e.getBlock().getState(false) instanceof Sign sign) {
            PersistentDataContainer pdc = sign.getPersistentDataContainer();
            pdc.set(ownerKey, PersistentDataType.STRING, p.getUniqueId().toString());
            pdc.set(priceKey, PersistentDataType.INTEGER, price);
            sign.update();
        }
        e.line(0, Component.text("[Shop]", NamedTextColor.DARK_GREEN));
        e.line(1, Component.text(price + " " + currency().name().toLowerCase(), NamedTextColor.GOLD));
        e.line(2, Component.text(p.getName()));
        p.sendMessage(Component.text("Shop created. Stock the chest; buyers right-click the sign.", NamedTextColor.GREEN));
    }

    @EventHandler(priority = EventPriority.HIGH)
    public void onBuy(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND || e.getAction() != Action.RIGHT_CLICK_BLOCK || e.getClickedBlock() == null) return;
        if (!(e.getClickedBlock().getState(false) instanceof Sign sign)) return;
        PersistentDataContainer pdc = sign.getPersistentDataContainer();
        String owner = pdc.get(ownerKey, PersistentDataType.STRING);
        Integer price = pdc.get(priceKey, PersistentDataType.INTEGER);
        if (owner == null || price == null) return;
        e.setCancelled(true);
        Player buyer = e.getPlayer();
        if (buyer.getUniqueId().toString().equals(owner)) { buyer.sendActionBar(Component.text("This is your shop: break the sign to remove it.", NamedTextColor.GRAY)); return; }
        Block chestBlock = chestBehind(e.getClickedBlock());
        if (chestBlock == null) { buyer.sendActionBar(Component.text("The shop chest is gone.", NamedTextColor.RED)); return; }
        Inventory stock = ((Container) chestBlock.getState(false)).getInventory();
        ItemStack sample = null;
        for (ItemStack it : stock.getContents()) if (it != null && !it.isEmpty() && it.getType() != currency()) { sample = it; break; }
        if (sample == null) { buyer.sendActionBar(Component.text("Sold out.", NamedTextColor.RED)); return; }
        if (!buyer.getInventory().containsAtLeast(new ItemStack(currency()), price)) { buyer.sendActionBar(Component.text("You need " + price + " " + currency().name().toLowerCase() + ".", NamedTextColor.RED)); return; }
        ItemStack money = new ItemStack(currency(), price);
        if (stock.firstEmpty() < 0 && !stock.containsAtLeast(new ItemStack(currency()), 1)) { buyer.sendActionBar(Component.text("The shop chest is full.", NamedTextColor.RED)); return; }
        ItemStack one = sample.asOne();
        if (!stock.removeItem(one).isEmpty()) return;
        buyer.getInventory().removeItem(money);
        if (!stock.addItem(money).isEmpty()) { // could not store the whole payment: undo the sale
            stock.addItem(one);
            buyer.getInventory().addItem(money);
            buyer.sendActionBar(Component.text("The shop chest is full.", NamedTextColor.RED));
            return;
        }
        buyer.getInventory().addItem(one).values().forEach(left -> buyer.getWorld().dropItemNaturally(buyer.getLocation(), left));
        sales++;
        buyer.sendActionBar(Component.text("Bought 1 for " + price + ".", NamedTextColor.GREEN));
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        Player p = e.getPlayer();
        if (p.hasPermission("goldenshop.admin")) return;
        Block b = e.getBlock();
        UUID me = p.getUniqueId();
        if (b.getState(false) instanceof Sign sign) {
            String owner = sign.getPersistentDataContainer().get(ownerKey, PersistentDataType.STRING);
            if (owner != null && !owner.equals(me.toString())) { e.setCancelled(true); p.sendActionBar(Component.text("Not your shop.", NamedTextColor.RED)); }
            return;
        }
        if (!(b.getState(false) instanceof Container)) return;
        for (BlockFace f : new BlockFace[] {BlockFace.NORTH, BlockFace.SOUTH, BlockFace.EAST, BlockFace.WEST}) {
            Block n = b.getRelative(f);
            if (!(n.getState(false) instanceof Sign sign) || !(n.getBlockData() instanceof Directional d) || d.getFacing() != f) continue;
            String owner = sign.getPersistentDataContainer().get(ownerKey, PersistentDataType.STRING);
            if (owner != null && !owner.equals(me.toString())) { e.setCancelled(true); p.sendActionBar(Component.text("Not your shop.", NamedTextColor.RED)); return; }
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(Component.text("GoldenChestShop: " + sales + " sales this session, currency " + currency().name() + ".", NamedTextColor.GREEN));
        return true;
    }
}
E
