package dev.nxeon.golden.crates;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.Sound;
import org.bukkit.block.Block;
import org.bukkit.block.Chest;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryDragEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryHolder;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden crates: a chest marked with /crate set becomes a crate (the mark lives on the chest's PersistentDataContainer, so it
 * survives restarts and needs no file). Right-click with a Crate Key (an item tagged in its PDC) spends the key and rolls one
 * weighted reward; right-click without a key shows the preview menu with odds. The roll is server-side, the key is consumed
 * BEFORE the reward is given, and a per-player cooldown stops double-click duplication.
 */
public class Crates extends JavaPlugin implements Listener {
    record Reward(Material item, int amount, int weight) {}

    static class Preview implements InventoryHolder {
        final Inventory inv = Bukkit.createInventory(this, 9, Component.text("Crate rewards"));
        @Override public Inventory getInventory() { return inv; }
    }

    private NamespacedKey keyKey;
    private NamespacedKey crateKey;
    private final List<Reward> rewards = new ArrayList<>();
    private final Map<UUID, Long> last = new HashMap<>();
    private final Set<String> placed = new HashSet<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        keyKey = new NamespacedKey(this, "crate_key");
        crateKey = new NamespacedKey(this, "crate");
        for (Map<?, ?> m : getConfig().getMapList("rewards")) {
            Object item = m.get("item"), amount = m.get("amount"), weight = m.get("weight");
            Material mat = item == null ? null : Material.matchMaterial(String.valueOf(item));
            int a = amount instanceof Number n ? n.intValue() : 1;
            int w = weight instanceof Number n ? n.intValue() : 1;
            if (mat != null && !mat.isAir() && a > 0 && w > 0) rewards.add(new Reward(mat, Math.min(a, 64), w));
        }
        getCommand("crate").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private int totalWeight() { return rewards.stream().mapToInt(Reward::weight).sum(); }

    private ItemStack keyItem() {
        ItemStack it = new ItemStack(Material.TRIPWIRE_HOOK);
        it.editMeta(m -> {
            m.displayName(Component.text("Crate Key", NamedTextColor.GOLD).decoration(TextDecoration.ITALIC, false));
            m.getPersistentDataContainer().set(keyKey, PersistentDataType.BOOLEAN, true);
        });
        return it;
    }

    private boolean isKey(ItemStack it) {
        return it != null && !it.isEmpty() && it.hasItemMeta() && it.getItemMeta().getPersistentDataContainer().has(keyKey, PersistentDataType.BOOLEAN);
    }

    private boolean isCrate(Block b) {
        return b.getState(false) instanceof Chest c && c.getPersistentDataContainer().has(crateKey, PersistentDataType.BOOLEAN);
    }

    private Reward roll() {
        int pick = ThreadLocalRandom.current().nextInt(totalWeight());
        for (Reward r : rewards) { pick -= r.weight(); if (pick < 0) return r; }
        return rewards.get(rewards.size() - 1);
    }

    @EventHandler(priority = EventPriority.HIGH)
    public void onUse(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND || e.getAction() != Action.RIGHT_CLICK_BLOCK || e.getClickedBlock() == null || !isCrate(e.getClickedBlock())) return;
        e.setCancelled(true); // never open the real chest
        Player p = e.getPlayer();
        if (rewards.isEmpty()) { p.sendActionBar(Component.text("This crate has no rewards configured.", NamedTextColor.RED)); return; }
        ItemStack hand = p.getInventory().getItemInMainHand();
        if (!isKey(hand)) {
            Preview pv = new Preview();
            int total = totalWeight();
            for (int i = 0; i < rewards.size() && i < 9; i++) {
                Reward r = rewards.get(i);
                ItemStack shown = new ItemStack(r.item(), r.amount());
                shown.editMeta(m -> m.lore(List.of(Component.text(String.format("%.1f%% chance", 100.0 * r.weight() / total), NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false))));
                pv.inv.setItem(i, shown);
            }
            p.openInventory(pv.inv);
            return;
        }
        long now = System.currentTimeMillis();
        long wait = Math.max(0, getConfig().getLong("cooldown-seconds", 2)) * 1000L;
        if (now - last.getOrDefault(p.getUniqueId(), 0L) < wait) return;
        last.put(p.getUniqueId(), now);
        hand.setAmount(hand.getAmount() - 1); // the key is spent first
        Reward r = roll();
        p.getInventory().addItem(new ItemStack(r.item(), r.amount())).values().forEach(left -> p.getWorld().dropItemNaturally(p.getLocation(), left));
        p.playSound(p.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 1f, 1.2f);
        p.sendMessage(Component.text("The crate gave you " + r.amount() + " " + r.item().name().toLowerCase().replace('_', ' ') + ".", NamedTextColor.GREEN));
    }

    @EventHandler public void onPreviewClick(InventoryClickEvent e) { if (e.getInventory().getHolder(false) instanceof Preview) e.setCancelled(true); }
    @EventHandler public void onPreviewDrag(InventoryDragEvent e) { if (e.getInventory().getHolder(false) instanceof Preview) e.setCancelled(true); }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        if (isCrate(e.getBlock()) && !e.getPlayer().hasPermission("goldencrates.admin")) { e.setCancelled(true); e.getPlayer().sendActionBar(Component.text("Crates are protected.", NamedTextColor.RED)); }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 0 || !(sender instanceof Player) && !(args.length >= 1 && args[0].equalsIgnoreCase("give"))) {
            sender.sendMessage(Component.text("GoldenCrates: " + rewards.size() + " rewards, total weight " + totalWeight() + ", " + placed.size() + " crates placed.", NamedTextColor.GREEN));
            return true;
        }
        if (!sender.hasPermission("goldencrates.admin")) { sender.sendMessage(Component.text("Admins only.", NamedTextColor.RED)); return true; }
        if (args[0].equalsIgnoreCase("give") && args.length == 2) {
            Player t = Bukkit.getPlayerExact(args[1]);
            if (t == null) { sender.sendMessage(Component.text("That player is not online.", NamedTextColor.RED)); return true; }
            t.getInventory().addItem(keyItem()).values().forEach(left -> t.getWorld().dropItemNaturally(t.getLocation(), left));
            sender.sendMessage(Component.text("Gave a crate key to " + t.getName() + ".", NamedTextColor.GREEN));
            return true;
        }
        if (args[0].equalsIgnoreCase("set") && sender instanceof Player p) {
            Block target = p.getTargetBlockExact(5);
            if (target == null || !(target.getState(false) instanceof Chest chest)) { p.sendMessage(Component.text("Look at a chest within 5 blocks.", NamedTextColor.RED)); return true; }
            chest.getPersistentDataContainer().set(crateKey, PersistentDataType.BOOLEAN, true);
            chest.update();
            placed.add(target.getWorld().getName() + ":" + target.getX() + "," + target.getY() + "," + target.getZ());
            p.sendMessage(Component.text("This chest is now a crate.", NamedTextColor.GREEN));
            return true;
        }
        sender.sendMessage(Component.text("/crate give <player> | /crate set", NamedTextColor.RED));
        return true;
    }
}
